{
  "lesson_summary": "Today's lesson plans to teach children to count numbers from 0 to 9, and to read and write these numbers both as numerals and in words. The lesson will use examples like counting two raised fingers and associating them with the numeral '2' and the word 'two'. It will also address common misconceptions, such as confusing the word 'five' with the numeral '6'.",
  "lesson_summary_short": "Today's lesson plans to teach children to count numbers from 0 to 9 and to read and write them as numerals and words, starting with two raised fingers.",
  "checks_summary": "This quiz checks whether the class can count objects, identify numerals, and match number words to their corresponding numerals, for numbers up to 9.",
  "questions": [
    {
      "slo_id": "S4",
      "level": "recall",
      "question": "Which of these is the numeral for the number 'six'?",
      "options": [
        "6",
        "5",
        "7"
      ],
      "correct_index": 0,
      "explanation": "The numeral '6' represents the quantity of six.",
      "selected_because": "Children confuse 'six' and 'five' due to similar sounds, this checks recall.",
      "distractor_misconceptions": {
        "1": "Confuses the numeral for 'five' with 'six'.",
        "2": "Confuses the numeral for 'seven' with 'six'."
      },
      "option_feedback": {
        "correct": "That's right! The numeral '6' shows the quantity of six.",
        "wrong": {
          "1": "This is the numeral for 'five'. Remember, '6' is the numeral for 'six'.",
          "2": "This is the numeral for 'seven'. The numeral '6' represents 'six'."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "How many butterflies are there in the picture?",
      "options": [
        "4",
        "5",
        "6"
      ],
      "correct_index": 1,
      "explanation": "Counting the butterflies in the picture shows there are 5 of them.",
      "selected_because": "Count the butterflies example from class practice.",
      "distractor_misconceptions": {
        "0": "Counts one less than the actual number.",
        "2": "Counts one more than the actual number."
      },
      "option_feedback": {
        "correct": "Excellent! There are 5 butterflies in the picture when you count them carefully.",
        "wrong": {
          "0": "Look closely and count each butterfly one by one. There are 5 butterflies.",
          "2": "Let's count again. Touch each butterfly as you count to make sure you get to 5."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "butterfly",
        "count": 5
      },
      "figure_role": "count_compare"
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "If you have two raised fingers, which numeral should you write?",
      "options": [
        "1",
        "2",
        "3"
      ],
      "correct_index": 1,
      "explanation": "When you count two raised fingers, the last count word is 'two', so you write the numeral '2'.",
      "selected_because": "Two raised fingers example from the worked example.",
      "distractor_misconceptions": {
        "0": "Confuses the numeral for 'one' with 'two'.",
        "2": "Confuses the numeral for 'three' with 'two'."
      },
      "option_feedback": {
        "correct": "That's right! Two raised fingers represent the numeral '2'.",
        "wrong": {
          "0": "One finger is '1'. Two fingers are '2'.",
          "2": "This is the numeral for 'three'. When you count two fingers, you write '2'."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S3",
      "level": "understand",
      "question": "Which word correctly spells the number shown by these flowers?",
      "options": [
        "four",
        "five",
        "six"
      ],
      "correct_index": 0,
      "explanation": "Counting the flowers shows there are 4, and 'four' is the correct word for this number.",
      "selected_because": "Counting flowers and writing the word.",
      "distractor_misconceptions": {
        "1": "Confuses the word 'five' with 'four'.",
        "2": "Confuses the word 'six' with 'four'."
      },
      "option_feedback": {
        "correct": "You got it! There are 4 flowers, and 'four' is how you write that number in words.",
        "wrong": {
          "1": "Count the flowers again. There are 4, not 5. The word for 4 is 'four'.",
          "2": "This word is 'six'. The picture shows 4 flowers, so the word should be 'four'."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "flower",
        "count": 4
      },
      "figure_role": "count_compare"
    },
    {
      "slo_id": "S5",
      "level": "understand",
      "question": "Which numeral matches the word 'four'?",
      "options": [
        "4",
        "5",
        "6"
      ],
      "correct_index": 0,
      "explanation": "The word 'four' represents the quantity that the numeral '4' shows.",
      "selected_because": "The example 'number word four in numerals'.",
      "distractor_misconceptions": {
        "1": "Confuses the numeral for 'five' with 'four'.",
        "2": "Confuses the numeral for 'six' with 'four'."
      },
      "option_feedback": {
        "correct": "That's correct! The numeral '4' is how we write the number word 'four'.",
        "wrong": {
          "1": "This is the numeral for 'five'. The word 'four' matches the numeral '4'.",
          "2": "This is the numeral for 'six'. The word 'four' is written as '4'."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "How many counters are in the ten-frame?",
      "options": [
        "7",
        "8",
        "9"
      ],
      "correct_index": 0,
      "explanation": "Counting the counters in the ten-frame shows there are 7 of them.",
      "selected_because": "Counting objects using a ten-frame.",
      "distractor_misconceptions": {
        "1": "Counts one more than the actual number.",
        "2": "Counts two more than the actual number."
      },
      "option_feedback": {
        "correct": "Great job! There are 7 counters in the ten-frame.",
        "wrong": {
          "1": "Count each counter carefully. There are 7 counters in the frame.",
          "2": "Let's count them again. Make sure you count each counter once to get to 7."
        }
      },
      "figure": {
        "type": "count_frame",
        "count": 7
      },
      "figure_role": "count_compare"
    },
    {
      "slo_id": "S3",
      "level": "apply",
      "question": "If you count six objects, which word should you write?",
      "options": [
        "five",
        "six",
        "seven"
      ],
      "correct_index": 1,
      "explanation": "When you count six objects, the last count word is 'six', so you write the word 'six'.",
      "selected_because": "Applying the concept of writing number words for a given count, addressing the 'five'/'six' confusion.",
      "distractor_misconceptions": {
        "0": "Confuses the word 'five' with 'six' due to similar sounds.",
        "2": "Confuses the word 'seven' with 'six'."
      },
      "option_feedback": {
        "correct": "That's correct! When you count six objects, you write the word 'six'.",
        "wrong": {
          "0": "Remember the lesson about 'five' and 'six'. When you count six objects, you write 'six'.",
          "2": "This word is 'seven'. When you count six objects, you write 'six'."
        }
      },
      "figure": null,
      "figure_role": null
    },
    {
      "slo_id": "S2",
      "level": "apply",
      "question": "Which numeral shows 'zero' objects?",
      "options": [
        "0",
        "1",
        "9"
      ],
      "correct_index": 0,
      "explanation": "The numeral '0' represents the absence of any objects, or 'zero'.",
      "selected_because": "Understanding the concept of zero and its numeral.",
      "distractor_misconceptions": {
        "1": "Confuses 'zero' with 'one'.",
        "2": "Confuses 'zero' with 'nine'."
      },
      "option_feedback": {
        "correct": "You're right! The numeral '0' means there are no objects.",
        "wrong": {
          "1": "This numeral '1' means one object. '0' means no objects.",
          "2": "This numeral '9' means nine objects. '0' means zero objects."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "counter",
        "count": 0
      },
      "figure_role": "model"
    }
  ]
}
